INSERT INTO "UniversityImage" ("id","universityId","url","alt","altAr","sortOrder") VALUES ('img_532fede4157cebc2e181','univ_0d2f013e4b2ab6e7e344','/img/universities/egyptian-e-learning-university/cover.jpg','Egyptian E-Learning University headquarters, Dokki','مقر الجامعة المصرية للتعلم الإلكتروني الأهلية بالدقي',0);
INSERT INTO "Faculty" ("id","universityId","name","nameAr","slug","description","descriptionAr","sortOrder","createdAt","updatedAt") VALUES ('fac_ba52fd0732d1028dc72d','univ_0d2f013e4b2ab6e7e344','Faculty of Computers and Information Technology','كلية الحاسبات وتكنولوجيا المعلومات','faculty-of-computers-and-information-technology','Study started under Ministerial Decree No. 3206 of 2009. Bachelor of Computing and Information Technology: 4 years, taught in English, 135 credit hours. Also offers a master''s in software engineering.','بدأت الدراسة بالكلية بالقرار الوزاري رقم 3206 لسنة 2009. تمنح بكالوريوس الحاسبات وتكنولوجيا المعلومات: 4 سنوات، الدراسة باللغة الإنجليزية، 135 ساعة معتمدة. كما تمنح ماجستير هندسة البرمجيات.',0,now(),now());
INSERT INTO "Faculty" ("id","universityId","name","nameAr","slug","description","descriptionAr","sortOrder","createdAt","updatedAt") VALUES ('fac_34c5bdb80b4f9ae5e299','univ_0d2f013e4b2ab6e7e344','Faculty of Business Administration and Commercial Studies','كلية إدارة الأعمال والدراسات التجارية','faculty-of-business-administration-and-commercial-studies','Bachelor''s degree in Management (144 credit hours), with a sub-specialization chosen in the third year: Marketing, Accounting, Finance and Investment, Supply Chain Management, or Management Information Systems.','تمنح درجة البكالوريوس في الإدارة (144 ساعة معتمدة)، مع اختيار تخصص فرعي في السنة الثالثة: التسويق، أو المحاسبة، أو التمويل والاستثمار، أو إدارة سلاسل الإمداد، أو نظم المعلومات الإدارية.',1,now(),now());
INSERT INTO "Faculty" ("id","universityId","name","nameAr","slug","description","descriptionAr","sortOrder","createdAt","updatedAt") VALUES ('fac_62961d394d7c0ce2a88a','univ_0d2f013e4b2ab6e7e344','Faculty of Educational Studies','كلية الدراسات التربوية','faculty-of-educational-studies','Postgraduate study only: General, Professional and Special Diplomas in Education, and a Master''s in Education.','دراسات عليا فقط: الدبلوم العام والدبلوم المهني والدبلوم الخاص في التربية، والماجستير في التربية.',2,now(),now());
INSERT INTO "Program" ("id","universityId","facultyId","name","nameAr","slug","description","descriptionAr","studyLevel","fieldOfStudy","durationMonths","durationLabel","durationLabelAr","tuitionFee","tuitionFeeMax","tuitionPeriod","currency","isPublished","createdAt","updatedAt") VALUES ('prog_5a53855359af75e294fa','univ_0d2f013e4b2ab6e7e344','fac_ba52fd0732d1028dc72d','Information Technology','تكنولوجيا المعلومات','information-technology','Admission: Thanaweya Amma science (math or science track), Azhar science, or equivalent Arab and foreign certificates. Fee: 61,868 EGP (math track) or 64,268 EGP (science track) for 2026/2027, including administrative fees, health insurance and student services.','القبول: الثانوية العامة علمي رياضة أو علمي علوم، أو الثانوية الأزهرية (علمي)، أو الشهادات العربية والأجنبية المعادلة. المصروفات: 61,868 جنيهًا (علمي رياضة) أو 64,268 جنيهًا (علمي علوم) للعام 2026/2027، وتشمل الرسوم الإدارية والتأمين الصحي والخدمات الطلابية.','BACHELOR','information_technology',48,'4 years (135 credit hours)','4 سنوات (135 ساعة معتمدة)',61868,64268,'YEAR','EGP',true,now(),now());
INSERT INTO "Program" ("id","universityId","facultyId","name","nameAr","slug","description","descriptionAr","studyLevel","fieldOfStudy","durationMonths","durationLabel","durationLabelAr","tuitionFee","tuitionFeeMax","tuitionPeriod","currency","isPublished","createdAt","updatedAt") VALUES ('prog_b9e97fe8893d25a512b7','univ_0d2f013e4b2ab6e7e344','fac_ba52fd0732d1028dc72d','Artificial Intelligence','الذكاء الاصطناعي','artificial-intelligence','Admission: Thanaweya Amma science (math or science track), Azhar science, or equivalent Arab and foreign certificates. Fee: 61,868 EGP (math track) or 64,268 EGP (science track) for 2026/2027, including administrative fees, health insurance and student services.','القبول: الثانوية العامة علمي رياضة أو علمي علوم، أو الثانوية الأزهرية (علمي)، أو الشهادات العربية والأجنبية المعادلة. المصروفات: 61,868 جنيهًا (علمي رياضة) أو 64,268 جنيهًا (علمي علوم) للعام 2026/2027، وتشمل الرسوم الإدارية والتأمين الصحي والخدمات الطلابية.','BACHELOR','artificial_intelligence',48,'4 years (135 credit hours)','4 سنوات (135 ساعة معتمدة)',61868,64268,'YEAR','EGP',true,now(),now());
INSERT INTO "Program" ("id","universityId","facultyId","name","nameAr","slug","description","descriptionAr","studyLevel","fieldOfStudy","durationMonths","durationLabel","durationLabelAr","tuitionFee","tuitionFeeMax","tuitionPeriod","currency","isPublished","createdAt","updatedAt") VALUES ('prog_1c3311bde83418f43b63','univ_0d2f013e4b2ab6e7e344','fac_ba52fd0732d1028dc72d','Data Science','علوم البيانات','data-science','Admission: Thanaweya Amma science (math or science track), Azhar science, or equivalent Arab and foreign certificates. Fee: 61,868 EGP (math track) or 64,268 EGP (science track) for 2026/2027, including administrative fees, health insurance and student services.','القبول: الثانوية العامة علمي رياضة أو علمي علوم، أو الثانوية الأزهرية (علمي)، أو الشهادات العربية والأجنبية المعادلة. المصروفات: 61,868 جنيهًا (علمي رياضة) أو 64,268 جنيهًا (علمي علوم) للعام 2026/2027، وتشمل الرسوم الإدارية والتأمين الصحي والخدمات الطلابية.','BACHELOR','data_science',48,'4 years (135 credit hours)','4 سنوات (135 ساعة معتمدة)',61868,64268,'YEAR','EGP',true,now(),now());
INSERT INTO "Program" ("id","universityId","facultyId","name","nameAr","slug","description","descriptionAr","studyLevel","fieldOfStudy","durationMonths","durationLabel","durationLabelAr","tuitionFee","tuitionFeeMax","tuitionPeriod","currency","isPublished","createdAt","updatedAt") VALUES ('prog_b38c4d47d457f27299aa','univ_0d2f013e4b2ab6e7e344','fac_34c5bdb80b4f9ae5e299','Business Administration','إدارة الأعمال','business-administration','Bachelor''s in Management with a third-year sub-specialization: Marketing, Accounting, Finance and Investment, Supply Chain Management, or Management Information Systems. Admission: Thanaweya Amma (science or arts), Azhar (science or arts), equivalent Arab certificates, American diploma, IG (8 subjects at grade C or above, including English), or the commercial technical diploma (3 or 5 years). Fee includes administrative fees, health insurance and student services.','بكالوريوس في الإدارة مع اختيار تخصص فرعي في السنة الثالثة: التسويق، أو المحاسبة، أو التمويل والاستثمار، أو إدارة سلاسل الإمداد، أو نظم المعلومات الإدارية. القبول: الثانوية العامة (علمي أو أدبي)، أو الأزهرية (علمي أو أدبي)، أو الثانوية العربية، أو الدبلومة الأمريكية، أو IG (8 مواد بتقدير C على الأقل منها اللغة الإنجليزية)، أو دبلوم المدارس التجارية (3 أو 5 سنوات). تشمل المصروفات الرسوم الإدارية والتأمين الصحي والخدمات الطلابية.','BACHELOR','business_administration',NULL,'144 credit hours','144 ساعة معتمدة',48612,NULL,'YEAR','EGP',true,now(),now());
